using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);

// Get all errors with full context
Console.WriteLine("=== ALL ERRORS (with file/line detail) ===");
var errors = build.FindChildrenRecursive<Error>();
foreach (var error in errors)
{
    Console.WriteLine(error.ToString());
    Console.WriteLine();
}

// Check if Api.csproj has any errors of its own
Console.WriteLine("=== CHECKING FOR MSB ERRORS (dependency failures) ===");
var messages = build.FindChildrenRecursive<Message>();
foreach (var m in messages)
{
    var text = m.ToString();
    if (text.Contains("MSB3202") || text.Contains("MSB4181") || text.Contains("could not be resolved") || text.Contains("failed") || text.Contains("error"))
    {
        // Check if it's from Api project
        var node = (BaseNode)m.Parent;
        while (node != null)
        {
            if (node is Project p && p.Name.Contains("Api"))
            {
                Console.WriteLine($"[Api] {text}");
                break;
            }
            node = node.Parent as BaseNode;
        }
    }
}

// Look at project dependencies
Console.WriteLine("\n=== PROJECT EVALUATION ORDER ===");
var projects = build.FindChildrenRecursive<Project>();
var seen = new HashSet<string>();
foreach (var p in projects)
{
    if (seen.Add(p.Name + p.TargetFramework))
        Console.WriteLine($"  {p.Name} (TF={p.TargetFramework})");
}
