// Dump the tree structure for Services.csproj build
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    if (p.Name != "Services.csproj") continue;

    // Look for all children recursively and print the tree
    PrintTree(p, 0, 3);
    break; // just first instance
}

void PrintTree(BaseNode node, int depth, int maxDepth)
{
    if (depth > maxDepth) return;
    var indent = new string(' ', depth * 2);
    var type = node.GetType().Name;
    var text = node.ToString();
    if (text.Length > 150) text = text[..150] + "...";

    // Filter to interesting nodes
    if (type == "Target" || type == "Task" || type == "Error" || type == "Warning" ||
        type == "AddItem" || type == "Item" || type == "Parameter" ||
        (type == "Message" && (text.Contains("Newtonsoft") || text.Contains("PackageReference") || text.Contains("package"))))
    {
        Console.WriteLine($"{indent}[{type}] {text}");
    }

    if (node is TreeNode tn)
    {
        foreach (var child in tn.Children.OfType<BaseNode>())
        {
            PrintTree(child, depth + 1, maxDepth);
        }
    }
}

// Also dump full text of all messages containing "Newtonsoft" or "package" 
Console.WriteLine("\n=== MESSAGES ABOUT PACKAGES ===");
var messages = build.FindChildrenRecursive<Message>();
foreach (var m in messages)
{
    var t = m.ToString();
    if (t.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase) || 
        t.Contains("PackageReference", StringComparison.OrdinalIgnoreCase))
    {
        Console.WriteLine(t);
    }
}

// Try to find NuGet restore issues
Console.WriteLine("\n=== RESTORE TARGET MESSAGES ===");
foreach (var m in messages)
{
    var t = m.ToString();
    if (t.Contains("restore", StringComparison.OrdinalIgnoreCase) && t.Contains("error", StringComparison.OrdinalIgnoreCase))
    {
        Console.WriteLine(t);
    }
}

// Look at NamedNode types
Console.WriteLine("\n=== NAMED NODES ===");
var named = build.FindChildrenRecursive<NamedNode>();
foreach (var n in named)
{
    var t = n.ToString();
    if (t.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase) || t.Contains("PackageReference", StringComparison.OrdinalIgnoreCase))
    {
        Console.WriteLine($"[{n.GetType().Name}] {t}");
    }
}
